def get_version(**_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        # match datastore style more closely
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, error_message=None, response_summary=None, duration_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "get_version",
            "request": {},
            "entity_id": None,
            "service_domain": None,
            "service_name": None,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    instances = _load("ha_instances.json")
    logs = _load("operation_logs.json")

    inst = _choose_instance(instances)
    if not inst:
        # still log against a synthetic "unknown" instance_id is not allowed by FK; return without logging
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")

    instance_id = inst.get("id")
    op_row = _append_op(logs, instance_id, "queued")
    # transition queued->running
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    ha_version = inst.get("ha_version")
    # "stale" policy: if last_seen_at older than 24h, we would refresh from HA; offline datastore cannot.
    # We still return the recorded version if present; otherwise UNAVAILABLE.
    if not isinstance(ha_version, str) or not ha_version.strip():
        dur = int((time.time() - t0) * 1000)
        op_row["status"] = "failed"
        op_row["duration_ms"] = dur
        op_row["error_message"] = "Mirror has no cached Home Assistant version yet."
        op_row["response_summary"] = {"has_version": False}
        op_row["updated_at"] = _now_iso()
        _save("operation_logs.json", logs)
        return _err("NOT_FOUND", "Home Assistant version is not available in the mirror yet.")

    # Update last_seen_at/updated_at because this is a successful interaction with the mirror
    now_iso = _now_iso()
    inst["last_seen_at"] = now_iso
    inst["updated_at"] = now_iso
    _save("ha_instances.json", instances)

    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = {"ha_version": ha_version}
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    return {
        "instance_id": instance_id,
        "ha_version": ha_version,
        "last_seen_at": inst.get("last_seen_at"),
    }

def get_entity(entity_id, fields=None, detailed=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    detailed = bool(detailed) if detailed is not None else False

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, request_obj, entity_id_for_log=None, error_message=None, response_summary=None, duration_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "get_entity",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": entity_id_for_log,
            "service_domain": None,
            "service_name": None,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    # Validate inputs
    if not isinstance(entity_id, str) or not entity_id.strip() or "." not in entity_id:
        return _err("VALIDATION_ERROR", "entity_id must be a non-empty string like 'domain.object_id'")

    if fields is not None:
        if not isinstance(fields, list) or any((not isinstance(x, str) or not x.strip()) for x in fields):
            return _err("VALIDATION_ERROR", "fields must be an array of strings or null")
    else:
        fields = None

    instances = _load("ha_instances.json")
    entities = _load("entities.json")
    logs = _load("operation_logs.json")

    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")
    instance_id = inst.get("id")

    op_row = _append_op(logs, instance_id, "queued", {"entity_id": entity_id, "fields": fields, "detailed": detailed}, entity_id_for_log=entity_id)
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    # Find entity by instance_id + entity_id; if missing, fall back to any instance that has it (to avoid bad default selection)
    def _find_entity(inst_id):
        for r in entities:
            if isinstance(r, dict) and r.get("instance_id") == inst_id and r.get("entity_id") == entity_id:
                return r
        return None

    ent = _find_entity(instance_id)
    if not ent:
        # try other eligible instances deterministically
        eligible_instances = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible_instances.sort(key=key)
        for alt in eligible_instances:
            if alt.get("id") == instance_id:
                continue
            alt_ent = _find_entity(alt.get("id"))
            if alt_ent:
                inst = alt
                instance_id = alt.get("id")
                ent = alt_ent
                break

    if not ent or ent.get("status") == "removed":
        dur = int((time.time() - t0) * 1000)
        op_row["status"] = "failed"
        op_row["duration_ms"] = dur
        op_row["error_message"] = f"Entity not found: {entity_id}"
        op_row["response_summary"] = {"found": False}
        op_row["updated_at"] = _now_iso()
        _save("operation_logs.json", logs)
        return _err("NOT_FOUND", "Entity not found in local mirror.", entity_id=entity_id)

    # Field projection policy: allow known top-level fields and attr.<path> into attributes dict.
    allowed_top = {
        "id", "instance_id", "entity_id", "domain", "friendly_name",
        "state", "attributes", "last_changed_at", "last_updated_at",
        "last_synced_at", "status", "created_at", "updated_at",
    }

    def _get_attr_path(obj, path):
        cur = obj
        for part in path.split("."):
            if not isinstance(cur, dict) or part not in cur:
                return None, False
            cur = cur[part]
        return cur, True

    if detailed or not fields:
        result = dict(ent)
    else:
        out = {"entity_id": ent.get("entity_id")}
        attrs = ent.get("attributes") if isinstance(ent.get("attributes"), dict) else {}
        for f in fields:
            if f in allowed_top:
                out[f] = ent.get(f)
            elif f.startswith("attr."):
                sub = f[len("attr.") :].strip()
                if not sub:
                    continue
                val, ok = _get_attr_path(attrs, sub)
                if ok:
                    out[f] = val
            else:
                # ignore unsupported selectors consistently (do not reject valid calls)
                continue
        result = out

    # Update instance last_seen_at on successful read
    now_iso = _now_iso()
    inst["last_seen_at"] = now_iso
    inst["updated_at"] = now_iso
    _save("ha_instances.json", instances)

    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = {"found": True, "returned_fields": ("full" if detailed or not fields else len(result))}
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    return {"instance_id": instance_id, "entity": result}

def entity_action(entity_id, action, params, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, request_obj, entity_id_for_log=None, service_domain=None, service_name=None, error_message=None, response_summary=None, duration_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "entity_action",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": entity_id_for_log,
            "service_domain": service_domain,
            "service_name": service_name,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    # Validate inputs
    if not isinstance(entity_id, str) or not entity_id.strip() or "." not in entity_id:
        return _err("VALIDATION_ERROR", "entity_id must be a non-empty string like 'domain.object_id'")
    if not isinstance(action, str) or action not in ("on", "off", "toggle"):
        return _err("VALIDATION_ERROR", "action must be one of: on, off, toggle", allowed=["on", "off", "toggle"])
    if not isinstance(params, str):
        return _err("VALIDATION_ERROR", "params must be a string")

    instances = _load("ha_instances.json")
    entities = _load("entities.json")
    logs = _load("operation_logs.json")

    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")
    instance_id = inst.get("id")

    # Interpret params:
    # - If params is JSON object string -> use as service data
    # - Else treat as opaque string (common audit defect showed instance_id passed here) and do not fail.
    service_data = None
    params_trim = params.strip()
    if params_trim:
        if params_trim.startswith("{") or params_trim.startswith("["):
            try:
                service_data = json.loads(params_trim)
            except json.JSONDecodeError:
                return _err("VALIDATION_ERROR", "params must be valid JSON when provided as JSON text")
        else:
            # opaque; keep for request logging only
            service_data = None

    # Find entity in mirror; if missing in default instance, search any eligible instance
    def _find_entity(inst_id):
        for r in entities:
            if isinstance(r, dict) and r.get("instance_id") == inst_id and r.get("entity_id") == entity_id:
                return r
        return None

    ent = _find_entity(instance_id)
    if not ent:
        eligible_instances = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible_instances.sort(key=key)
        for alt in eligible_instances:
            alt_ent = _find_entity(alt.get("id"))
            if alt_ent:
                inst = alt
                instance_id = alt.get("id")
                ent = alt_ent
                break

    domain = entity_id.split(".", 1)[0]

    # Create op log queued->running
    op_row = _append_op(
        logs,
        instance_id,
        "queued",
        {"entity_id": entity_id, "action": action, "params": params},
        entity_id_for_log=entity_id,
        service_domain=domain,
        service_name={"on": "turn_on", "off": "turn_off", "toggle": "toggle"}[action],
    )
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    if not ent or ent.get("status") == "removed":
        dur = int((time.time() - t0) * 1000)
        op_row["status"] = "failed"
        op_row["duration_ms"] = dur
        op_row["error_message"] = f"Entity not found: {entity_id}"
        op_row["response_summary"] = {"called": False}
        op_row["updated_at"] = _now_iso()
        _save("operation_logs.json", logs)
        return _err("NOT_FOUND", "Entity not found in local mirror.", entity_id=entity_id)

    # Offline HA call simulation: apply minimal mirror mutation to reflect intent.
    # (Real service would call HA; here we persist a local state update as observable effect.)
    now_iso = _now_iso()
    old_state = ent.get("state")
    new_state = old_state
    if action == "on":
        new_state = "on"
    elif action == "off":
        new_state = "off"
    elif action == "toggle":
        if isinstance(old_state, str) and old_state.lower() in ("on", "off"):
            new_state = "off" if old_state.lower() == "on" else "on"
        else:
            new_state = "on"

    ent["state"] = new_state
    ent["last_updated_at"] = now_iso
    ent["updated_at"] = now_iso
    # update instance last_seen_at as "interaction"
    inst["last_seen_at"] = now_iso
    inst["updated_at"] = now_iso
    _save("entities.json", entities)
    _save("ha_instances.json", instances)

    # Append a history row if unique constraint allows (instance_id, entity_id, changed_at)
    history = _load("entity_state_history.json")
    changed_at = now_iso
    exists = False
    for h in history:
        if isinstance(h, dict) and h.get("instance_id") == instance_id and h.get("entity_id") == entity_id and h.get("changed_at") == changed_at:
            exists = True
            break
    if not exists:
        history.append({
            "id": _new_id("hist"),
            "instance_id": instance_id,
            "entity_id": entity_id,
            "entity_pk": ent.get("id"),
            "state": new_state,
            "attributes": ent.get("attributes") if isinstance(ent.get("attributes"), dict) else None,
            "changed_at": changed_at,
            "source": "manual_import",
            "created_at": now_iso,
            "updated_at": now_iso,
        })
        _save("entity_state_history.json", history)

    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = {"called": True, "service": f"{domain}.{op_row['service_name']}", "state_before": old_state, "state_after": new_state}
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    return {
        "instance_id": instance_id,
        "entity_id": entity_id,
        "action": action,
        "service_call": {
            "domain": domain,
            "service": op_row["service_name"],
            "data": service_data if isinstance(service_data, (dict, list)) else {},
        },
        "result": {"state_before": old_state, "state_after": new_state},
    }

def list_entities(domain=None, search_query=None, limit=None, fields=None, detailed=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    detailed = bool(detailed) if detailed is not None else False
    if limit is None:
        limit = 100

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            try:
                if s.endswith("Z"):
                    s = s[:-1] + "+00:00"
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _choose_instance(instances):
        active = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not active:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at"))
            return (dt or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or "")
        active.sort(key=key)
        return active[0]

    def _log(instance_id, tool_name, request_obj, status, duration_ms=None, error_message=None, response_summary=None):
        logs = _load("operation_logs.json")
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": tool_name,
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": None,
            "service_domain": None,
            "service_name": None,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        _save("operation_logs.json", logs)
        return row

    def _finalize(op_id, ok, payload=None, err=None, response_summary=None):
        dur = int((time.time() - t0) * 1000)
        logs = _load("operation_logs.json")
        for i in range(len(logs) - 1, -1, -1):
            if logs[i].get("id") == op_id:
                logs[i]["duration_ms"] = dur
                logs[i]["updated_at"] = _now_iso()
                logs[i]["response_summary"] = response_summary
                if ok:
                    logs[i]["status"] = "succeeded"
                else:
                    logs[i]["status"] = "failed"
                    logs[i]["error_message"] = err["error"]["message"] if isinstance(err, dict) and "error" in err else "Operation failed"
                break
        _save("operation_logs.json", logs)
        return payload if ok else err

    # Validate limit
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.")
    if limit < 1 or limit > 500:
        return _err("VALIDATION_ERROR", "limit must be between 1 and 500.")

    if domain is not None and (not isinstance(domain, str) or not domain.strip()):
        return _err("VALIDATION_ERROR", "domain must be a non-empty string or null.")
    if search_query is not None and (not isinstance(search_query, str)):
        return _err("VALIDATION_ERROR", "search_query must be a string or null.")
    if fields is not None:
        if not isinstance(fields, list) or any((not isinstance(x, str) or not x.strip()) for x in fields):
            return _err("VALIDATION_ERROR", "fields must be an array of non-empty strings or null.")

    instances = _load("ha_instances.json")
    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No active Home Assistant instance is configured to serve this request.")

    op_req = {"domain": domain, "search_query": search_query, "limit": limit, "fields": fields, "detailed": detailed}
    op = _log(inst["id"], "list_entities", op_req, "queued")
    # queued->running
    logs = _load("operation_logs.json")
    for i in range(len(logs) - 1, -1, -1):
        if logs[i].get("id") == op["id"]:
            logs[i]["status"] = "running"
            logs[i]["updated_at"] = _now_iso()
            break
    _save("operation_logs.json", logs)

    ents = _load("entities.json")
    inst_ents = [e for e in ents if isinstance(e, dict) and e.get("instance_id") == inst.get("id") and e.get("status") != "removed"]

    if len(inst_ents) == 0:
        return _finalize(op["id"], False, err=_err("CONFLICT", "Local mirror is not ready to serve reads (no entities synced yet)."))

    if domain is not None:
        d = domain.strip()
        inst_ents = [e for e in inst_ents if e.get("domain") == d]

    if search_query is not None and search_query.strip():
        q = search_query.strip().lower()
        filtered = []
        for e in inst_ents:
            hay = []
            eid = e.get("entity_id") or ""
            fn = e.get("friendly_name") or ""
            hay.append(str(eid).lower())
            hay.append(str(fn).lower())
            attrs = e.get("attributes")
            if attrs is not None:
                try:
                    hay.append(json.dumps(attrs, ensure_ascii=False).lower())
                except TypeError:
                    hay.append(str(attrs).lower())
            if any(q in h for h in hay):
                filtered.append(e)
        inst_ents = filtered

    # Sort deterministically by entity_id
    inst_ents.sort(key=lambda r: (r.get("domain") or "", r.get("entity_id") or ""))

    total = len(inst_ents)
    page = inst_ents[:limit]

    if detailed or fields is None:
        payload = {
            "entities": page,
            "meta": {"total": total, "returned": len(page), "limit": limit, "has_more": total > len(page), "next_cursor": None},
        }
        return _finalize(op["id"], True, payload=payload, response_summary={"total": total, "returned": len(page)})

    allowed_top = {
        "id", "instance_id", "entity_id", "domain", "friendly_name", "state", "attributes",
        "last_changed_at", "last_updated_at", "last_synced_at", "status", "created_at", "updated_at"
    }

    bad = []
    def _project(row):
        proj = {}
        attrs = row.get("attributes") if isinstance(row.get("attributes"), dict) else {}
        for sel in fields:
            s = sel.strip()
            if s.startswith("attr."):
                path = s[5:]
                if not path:
                    if sel not in bad:
                        bad.append(sel)
                    continue
                cur = attrs
                ok = True
                for part in path.split("."):
                    if isinstance(cur, dict) and part in cur:
                        cur = cur[part]
                    else:
                        ok = False
                        break
                proj[s] = cur if ok else None
            else:
                if s not in allowed_top:
                    if sel not in bad:
                        bad.append(sel)
                else:
                    proj[s] = row.get(s)
        return proj

    projected_rows = []
    for r in page:
        projected_rows.append({"entity_id": r.get("entity_id"), "fields": _project(r)})

    if bad:
        return _finalize(op["id"], False, err=_err("VALIDATION_ERROR", "Unsupported field selectors.", unsupported=bad))

    payload = {
        "entities": projected_rows,
        "meta": {"total": total, "returned": len(projected_rows), "limit": limit, "has_more": total > len(projected_rows), "next_cursor": None},
    }
    return _finalize(op["id"], True, payload=payload, response_summary={"total": total, "returned": len(projected_rows)})

def search_entities_tool(query, limit=20, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    s2 = s[:-1]
                    return datetime.datetime.fromisoformat(s2)
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        # deterministic enough for local store
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"

    def _select_instance(instances):
        active = [r for r in instances if r.get("status") == "active"]
        if not active:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at"))
            return (dt or datetime.datetime.max, r.get("id") or "")
        active.sort(key=key)
        return active[0]

    def _log_transition(logs, row, new_status, duration_ms=None, error_message=None, response_summary=None):
        old = row.get("status")
        allowed = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": [],
        }
        if new_status not in allowed.get(old, []):
            # If the store is inconsistent, force to failed to avoid crashing.
            new_status = "failed"
            error_message = error_message or f"Invalid status transition from {old} to {new_status}"
        row["status"] = new_status
        if duration_ms is not None:
            row["duration_ms"] = duration_ms
        if error_message is not None:
            row["error_message"] = error_message
        if response_summary is not None:
            row["response_summary"] = response_summary
        row["updated_at"] = _now_iso()
        return row

    t0 = time.time()

    instances = _load("ha_instances.json")
    entities = _load("entities.json")
    logs = _load("operation_logs.json")

    inst = _select_instance(instances)
    if not inst:
        # cannot even create a valid operation log row without instance_id per schema
        return _err("UNAUTHORIZED", "No active Home Assistant instance is configured")

    # Create operation log row (queued -> running -> ...), always
    log_row = {
        "id": _new_id("oplog"),
        "instance_id": inst.get("id"),
        "tool_name": "search_entities_tool",
        "request": {"query": query, "limit": limit},
        "entity_id": None,
        "service_domain": None,
        "service_name": None,
        "response_summary": None,
        "error_message": None,
        "duration_ms": None,
        "status": "queued",
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    logs.append(log_row)
    _save("operation_logs.json", logs)

    # Validate
    if not isinstance(query, str):
        _log_transition(logs, log_row, "failed", error_message="query must be a string")
        _save("operation_logs.json", logs)
        return _err("VALIDATION_ERROR", "query must be a string")
    if limit is None:
        limit = 20
    if not isinstance(limit, int):
        _log_transition(logs, log_row, "failed", error_message="limit must be an integer")
        _save("operation_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit must be an integer")
    if limit < 1 or limit > 200:
        _log_transition(logs, log_row, "failed", error_message="limit must be between 1 and 200")
        _save("operation_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit must be between 1 and 200")

    _log_transition(logs, log_row, "running")
    _save("operation_logs.json", logs)

    q = query.strip().lower()
    def _matches(e):
        if e.get("instance_id") != inst.get("id"):
            return False
        if e.get("status") == "removed":
            return False
        if q == "":
            return True
        hay = []
        eid = e.get("entity_id") or ""
        fn = e.get("friendly_name") or ""
        hay.append(eid)
        hay.append(fn)
        attrs = e.get("attributes")
        if attrs is not None:
            try:
                hay.append(json.dumps(attrs, ensure_ascii=False, sort_keys=True))
            except Exception:
                hay.append(str(attrs))
        blob = " ".join([h for h in hay if isinstance(h, str)])
        return q in blob.lower()

    filtered = [e for e in entities if _matches(e)]
    total = len(filtered)

    # Deterministic ordering: domain, entity_id
    def _sort_key(e):
        return (e.get("domain") or "", e.get("entity_id") or "", e.get("id") or "")
    filtered.sort(key=_sort_key)

    results = []
    for e in filtered[:limit]:
        results.append({
            "entity_id": e.get("entity_id"),
            "domain": e.get("domain"),
            "friendly_name": e.get("friendly_name"),
            "state": e.get("state"),
            "status": e.get("status"),
        })

    duration_ms = int((time.time() - t0) * 1000)
    _log_transition(
        logs,
        log_row,
        "succeeded",
        duration_ms=duration_ms,
        response_summary={"returned": len(results), "total": total},
    )
    _save("operation_logs.json", logs)

    return {
        "count": total,
        "returned": len(results),
        "limit": limit,
        "results": results,
    }

def domain_summary_tool(domain, example_limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                # fromisoformat doesn't parse Z; treat as UTC naive
                return datetime.datetime.fromisoformat(s2)
            return datetime.datetime.fromisoformat(s)
        except ValueError:
            return None

    def _new_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _choose_instance(instances):
        # Choose a single "active" instance deterministically by lowest created_at then id.
        # If none are active, try degraded/offline deterministically; fail only if none exist.
        def key(r):
            cd = _parse_dt(r.get("created_at")) or datetime.datetime.max
            return (cd, r.get("id") or "")
        active = [r for r in instances if r.get("status") == "active"]
        if active:
            return sorted(active, key=key)[0]
        usable = [r for r in instances if r.get("status") in ("degraded", "offline")]
        if usable:
            return sorted(usable, key=key)[0]
        any_inst = [r for r in instances if isinstance(r, dict) and r.get("id")]
        if any_inst:
            return sorted(any_inst, key=key)[0]
        return None

    def _log_transition(logs, log_row, new_status, duration_ms=None, error_message=None, response_summary=None):
        # Enforce lifecycle transitions for operation_logs.status
        allowed = {
            "queued": set(["running", "cancelled", "failed"]),
            "running": set(["succeeded", "failed", "cancelled"]),
            "succeeded": set(),
            "failed": set(),
            "cancelled": set(),
        }
        cur = log_row.get("status")
        if cur not in allowed or new_status not in allowed[cur]:
            # If logging can't follow transitions, do not crash the tool; best-effort mark failed if possible
            return False
        log_row["status"] = new_status
        if duration_ms is not None:
            log_row["duration_ms"] = duration_ms
        if error_message is not None:
            log_row["error_message"] = error_message
        if response_summary is not None:
            log_row["response_summary"] = response_summary
        log_row["updated_at"] = _now_iso()
        return True

    t0 = time.time()

    # Validate inputs
    if not isinstance(domain, str) or not domain.strip():
        return _err("VALIDATION_ERROR", "domain must be a non-empty string", field="domain")
    domain = domain.strip()

    if example_limit is None:
        example_limit = 3
    if not isinstance(example_limit, int):
        return _err("VALIDATION_ERROR", "example_limit must be an integer", field="example_limit")
    if example_limit < 1 or example_limit > 20:
        return _err("VALIDATION_ERROR", "example_limit must be between 1 and 20", field="example_limit")

    instances = _load("ha_instances.json")
    entities = _load("entities.json")
    logs = _load("operation_logs.json")

    inst = _choose_instance(instances)
    if not inst or not inst.get("id"):
        # No usable authenticated context available in store
        # Log is not possible without an instance_id row; return UNAUTHORIZED per contract.
        return _err("UNAUTHORIZED", "No Home Assistant instance is configured/available")

    instance_id = inst["id"]

    # Create operation log with queued -> running -> (succeeded|failed)
    log_row = {
        "id": _new_id("oplog"),
        "instance_id": instance_id,
        "tool_name": "domain_summary_tool",
        "request": {"domain": domain, "example_limit": example_limit},
        "entity_id": None,
        "service_domain": None,
        "service_name": None,
        "response_summary": None,
        "error_message": None,
        "duration_ms": None,
        "status": "queued",
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    logs.append(log_row)
    _save("operation_logs.json", logs)

    _log_transition(logs, log_row, "running")
    _save("operation_logs.json", logs)

    try:
        # Filter entities by instance/domain and status != removed
        filtered = []
        for e in entities:
            if not isinstance(e, dict):
                continue
            if e.get("instance_id") != instance_id:
                continue
            if e.get("domain") != domain:
                continue
            if e.get("status") == "removed":
                continue
            filtered.append(e)

        total_count = len(filtered)

        # Compute distribution and deterministic examples (by entity_id then id)
        def ekey(e):
            return (e.get("entity_id") or "", e.get("id") or "")

        state_distribution = {}
        by_state = {}
        for e in filtered:
            st = e.get("state")
            if st is None:
                st = "unknown"
            if not isinstance(st, str):
                st = str(st)
            state_distribution[st] = state_distribution.get(st, 0) + 1
            by_state.setdefault(st, []).append(e)

        examples = {}
        for st, rows in by_state.items():
            rows_sorted = sorted(rows, key=ekey)
            sample = rows_sorted[:example_limit]
            # Store safe, compact example entity objects (mirror rows; not fabricating)
            examples[st] = [
                {
                    "entity_id": r.get("entity_id"),
                    "friendly_name": r.get("friendly_name"),
                    "state": r.get("state"),
                    "attributes": r.get("attributes"),
                    "last_changed_at": r.get("last_changed_at"),
                    "last_updated_at": r.get("last_updated_at"),
                    "status": r.get("status"),
                }
                for r in sample
            ]

        result = {
            "domain": domain,
            "total_count": total_count,
            "state_distribution": dict(sorted(state_distribution.items(), key=lambda kv: (-kv[1], kv[0]))),
            "examples": examples,
        }

        duration_ms = int((time.time() - t0) * 1000)
        _log_transition(
            logs,
            log_row,
            "succeeded",
            duration_ms=duration_ms,
            response_summary={
                "total_count": total_count,
                "distinct_states": len(state_distribution),
                "example_limit": example_limit,
            },
        )
        _save("operation_logs.json", logs)
        return result

    except Exception as e:
        duration_ms = int((time.time() - t0) * 1000)
        # Best-effort failure logging; do not hide programming errors as successful responses.
        _log_transition(logs, log_row, "failed", duration_ms=duration_ms, error_message=str(e))
        _save("operation_logs.json", logs)
        return _err("CONFLICT", "Unexpected failure while computing domain summary", detail=str(e))

def system_overview(limit_per_domain=None, include_attributes=None, include_state_distributions=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, (int, float)):
            return datetime.datetime.utcfromtimestamp(s)
        if isinstance(s, str):
            try:
                if s.endswith("Z"):
                    return datetime.datetime.fromisoformat(s[:-1])
                return datetime.datetime.fromisoformat(s)
            except Exception:
                return None
        return None

    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}"

    def _select_instance(instances):
        active = [r for r in instances if r.get("status") == "active"]
        if not active:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at"))
            return (dt or datetime.datetime.max, r.get("id") or "")
        active.sort(key=key)
        return active[0]

    def _log_transition(logs, row, new_status, duration_ms=None, error_message=None, response_summary=None):
        allowed = {
            "queued": ["running", "cancelled", "failed"],
            "running": ["succeeded", "failed", "cancelled"],
            "succeeded": [],
            "failed": [],
            "cancelled": [],
        }
        old = row.get("status")
        if new_status not in allowed.get(old, []):
            new_status = "failed"
            error_message = error_message or f"Invalid status transition from {old} to {new_status}"
        row["status"] = new_status
        if duration_ms is not None:
            row["duration_ms"] = duration_ms
        if error_message is not None:
            row["error_message"] = error_message
        if response_summary is not None:
            row["response_summary"] = response_summary
        row["updated_at"] = _now_iso()
        return row

    t0 = time.time()

    instances = _load("ha_instances.json")
    entities = _load("entities.json")
    logs = _load("operation_logs.json")

    inst = _select_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No active Home Assistant instance is configured")

    # defaults
    if limit_per_domain is None:
        limit_per_domain = 3
    if include_attributes is None:
        include_attributes = True
    if include_state_distributions is None:
        include_state_distributions = True

    log_row = {
        "id": _new_id("oplog"),
        "instance_id": inst.get("id"),
        "tool_name": "system_overview",
        "request": {
            "limit_per_domain": limit_per_domain,
            "include_attributes": include_attributes,
            "include_state_distributions": include_state_distributions,
        },
        "entity_id": None,
        "service_domain": None,
        "service_name": None,
        "response_summary": None,
        "error_message": None,
        "duration_ms": None,
        "status": "queued",
        "created_at": _now_iso(),
        "updated_at": _now_iso(),
    }
    logs.append(log_row)
    _save("operation_logs.json", logs)

    # Validate
    if not isinstance(limit_per_domain, int):
        _log_transition(logs, log_row, "failed", error_message="limit_per_domain must be an integer")
        _save("operation_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit_per_domain must be an integer")
    if limit_per_domain < 0:
        _log_transition(logs, log_row, "failed", error_message="limit_per_domain must be non-negative")
        _save("operation_logs.json", logs)
        return _err("VALIDATION_ERROR", "limit_per_domain must be non-negative")
    if not isinstance(include_attributes, bool):
        _log_transition(logs, log_row, "failed", error_message="include_attributes must be a boolean")
        _save("operation_logs.json", logs)
        return _err("VALIDATION_ERROR", "include_attributes must be a boolean")
    if not isinstance(include_state_distributions, bool):
        _log_transition(logs, log_row, "failed", error_message="include_state_distributions must be a boolean")
        _save("operation_logs.json", logs)
        return _err("VALIDATION_ERROR", "include_state_distributions must be a boolean")

    _log_transition(logs, log_row, "running")
    _save("operation_logs.json", logs)

    rows = [e for e in entities if e.get("instance_id") == inst.get("id") and e.get("status") != "removed"]

    if not rows:
        duration_ms = int((time.time() - t0) * 1000)
        _log_transition(logs, log_row, "failed", duration_ms=duration_ms, error_message="No synchronized entities available")
        _save("operation_logs.json", logs)
        return _err("NOT_FOUND", "Mirror is not ready or contains no synchronized entities")

    per_domain = {}
    for e in rows:
        dom = e.get("domain") or "unknown"
        per_domain.setdefault(dom, []).append(e)

    domain_counts = {d: len(v) for d, v in per_domain.items()}

    domain_samples = {}
    for d, v in per_domain.items():
        v_sorted = sorted(v, key=lambda e: (e.get("entity_id") or "", e.get("id") or ""))
        sample = v_sorted[:limit_per_domain] if limit_per_domain > 0 else []
        domain_samples[d] = [{
            "entity_id": e.get("entity_id"),
            "friendly_name": e.get("friendly_name"),
            "state": e.get("state"),
            "status": e.get("status"),
        } for e in sample]

    state_distributions = None
    if include_state_distributions:
        state_distributions = {}
        for d, v in per_domain.items():
            dist = {}
            for e in v:
                st = e.get("state")
                st = st if st is not None else "unknown"
                dist[st] = dist.get(st, 0) + 1
            state_distributions[d] = dist

    common_attributes = None
    area_distribution = None
    if include_attributes:
        common_attributes = {}
        area_distribution = {}
        for d, v in per_domain.items():
            key_counts = {}
            area_counts = {}
            for e in v:
                attrs = e.get("attributes")
                if isinstance(attrs, dict):
                    for k in attrs.keys():
                        key_counts[k] = key_counts.get(k, 0) + 1
                    area = attrs.get("area") or attrs.get("area_id") or attrs.get("area_name")
                    if isinstance(area, str) and area.strip():
                        area_counts[area] = area_counts.get(area, 0) + 1
            # frequent keys: appear in >= 30% of entities in domain, cap 20
            threshold = max(1, int(len(v) * 0.3))
            frequent = [k for k, c in key_counts.items() if c >= threshold]
            frequent.sort(key=lambda k: (-key_counts.get(k, 0), k))
            common_attributes[d] = [{"key": k, "count": key_counts[k]} for k in frequent[:20]]
            if area_counts:
                area_distribution[d] = dict(sorted(area_counts.items(), key=lambda kv: (-kv[1], kv[0])))

        if not area_distribution:
            area_distribution = None

    duration_ms = int((time.time() - t0) * 1000)
    _log_transition(
        logs,
        log_row,
        "succeeded",
        duration_ms=duration_ms,
