def list_automations(limit=None, status=None, fields=None, detailed=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    detailed = bool(detailed) if detailed is not None else False

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, request_obj, error_message=None, response_summary=None, duration_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "list_automations",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": None,
            "service_domain": None,
            "service_name": None,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    # Validate inputs (relax fields: ignore unknown rather than rejecting)
    if limit is not None:
        if not isinstance(limit, int) or limit < 0:
            return _err("VALIDATION_ERROR", "limit must be a non-negative integer")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "removed"):
            return _err("VALIDATION_ERROR", "status must be one of: active, removed")
    if fields is not None:
        if not isinstance(fields, list) or any((not isinstance(x, str) or not x.strip()) for x in fields):
            return _err("VALIDATION_ERROR", "fields must be an array of strings when provided")

    instances = _load("ha_instances.json")
    autos = _load("automations.json")
    logs = _load("operation_logs.json")

    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")
    instance_id = inst.get("id")

    op_row = _append_op(logs, instance_id, "queued", {"limit": limit, "status": status, "fields": fields, "detailed": detailed})
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    rows = [r for r in autos if isinstance(r, dict) and r.get("instance_id") == instance_id]
    if status is not None:
        rows = [r for r in rows if r.get("status") == status]

    # default behavior expected by business rule: list active if mirror used for automations
    if status is None:
        rows = [r for r in rows if r.get("status") == "active"]

    def _sort_key(r):
        return (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), r.get("id") or "")
    rows.sort(key=_sort_key)

    total = len(rows)
    if limit is not None:
        rows = rows[:limit]

    allowed_top = {
        "id", "instance_id", "automation_id", "entity_id", "alias",
        "state", "last_synced_at", "status", "created_at", "updated_at",
    }

    if detailed or not fields:
        out_rows = [dict(r) for r in rows]
    else:
        out_rows = []
        for r in rows:
            o = {"entity_id": r.get("entity_id")}
            for f in fields:
                if f in allowed_top:
                    o[f] = r.get(f)
                else:
                    # ignore unsupported field names (do not reject the whole call)
                    continue
            out_rows.append(o)

    # Update instance last_seen_at on successful read
    now_iso = _now_iso()
    inst["last_seen_at"] = now_iso
    inst["updated_at"] = now_iso
    _save("ha_instances.json", instances)

    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = {"returned": len(out_rows), "total": total}
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    return {"instance_id": instance_id, "total": total, "automations": out_rows}

def restart_ha(reason=None, timeout_s=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, request_obj, error_message=None, response_summary=None, duration_ms=None, service_domain=None, service_name=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "restart_ha",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": None,
            "service_domain": service_domain,
            "service_name": service_name,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    # Validate inputs
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "reason must be a string when provided")
    if timeout_s is not None:
        if not isinstance(timeout_s, int) or timeout_s < 0:
            return _err("VALIDATION_ERROR", "timeout_s must be a non-negative integer when provided")

    instances = _load("ha_instances.json")
    logs = _load("operation_logs.json")
    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")
    instance_id = inst.get("id")

    # must allow only when instance.status in {'active','degraded'}
    if inst.get("status") not in ("active", "degraded"):
        # still audit the attempt
        op_row = _append_op(logs, instance_id, "queued", {"reason": reason, "timeout_s": timeout_s}, service_domain="homeassistant", service_name="restart")
        op_row["status"] = "running"
        op_row["updated_at"] = _now_iso()
        dur = int((time.time() - t0) * 1000)
        op_row["status"] = "failed"
        op_row["duration_ms"] = dur
        op_row["error_message"] = f"Restart blocked: instance status is '{inst.get('status')}'"
        op_row["updated_at"] = _now_iso()
        _save("operation_logs.json", logs)
        return _err("INVALID_TRANSITION", "restart_ha is only allowed when instance status is active or degraded.", status=inst.get("status"))

    # Do not falsely CONFLICT; only conflict if there is a *running* restart_ha op for this instance.
    in_progress = []
    for r in logs:
        if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("tool_name") == "restart_ha" and r.get("status") in ("queued", "running"):
            in_progress.append(r.get("id"))
    if in_progress:
        op_row = _append_op(logs, instance_id, "queued", {"reason": reason, "timeout_s": timeout_s}, service_domain="homeassistant", service_name="restart")
        op_row["status"] = "running"
        op_row["updated_at"] = _now_iso()
        dur = int((time.time() - t0) * 1000)
        op_row["status"] = "failed"
        op_row["duration_ms"] = dur
        op_row["error_message"] = "A restart is already in progress."
        op_row["response_summary"] = {"in_progress_operation_ids": in_progress}
        op_row["updated_at"] = _now_iso()
        _save("operation_logs.json", logs)
        return _err("CONFLICT", "A restart is already in progress.", in_progress_operation_ids=in_progress)

    # Create op log queued->running
    op_row = _append_op(logs, instance_id, "queued", {"reason": reason, "timeout_s": timeout_s}, service_domain="homeassistant", service_name="restart")
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    # Offline restart simulation: mark instance degraded and bump last_seen_at
    now_iso = _now_iso()
    inst["status"] = "degraded"
    inst["last_seen_at"] = now_iso
    inst["updated_at"] = now_iso
    _save("ha_instances.json", instances)

    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = {"requested": True, "instance_status": inst.get("status")}
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    return {"instance_id": instance_id, "requested": True, "status": inst.get("status"), "operation_id": op_row.get("id")}

def call_service_tool(domain, service, data=None, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc).replace(tzinfo=None)
        except Exception:
            return None

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    start = time.time()
    instances = _load("ha_instances.json")
    ops = _load("operation_logs.json")

    # Pick an instance that can serve calls: status not disabled
    def _inst_sort_key(r):
        created = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1)
        return (created, r.get("id") or "")
    candidates = [r for r in instances if r.get("status") in ("active", "degraded", "offline")]
    if not candidates:
        # if only disabled exist, unauthorized
        if instances:
            return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available for service calls.")
        return _err("UNAUTHORIZED", "No Home Assistant instance is configured.")
    instance = sorted(candidates, key=_inst_sort_key)[0]
    instance_id = instance.get("id")

    # Create operation log (queued -> running -> final)
    op_id = _gen_id("op")
    op_row = {
        "id": op_id,
        "instance_id": instance_id,
        "tool_name": "call_service_tool",
        "request": {"domain": domain, "service": service, "data": data},
        "entity_id": None,
        "service_domain": domain,
        "service_name": service,
        "response_summary": None,
        "error_message": None,
        "duration_ms": None,
        "status": "queued",
        "created_at": _now(),
        "updated_at": _now(),
    }
    ops.append(op_row)
    _save("operation_logs.json", ops)

    op_row["status"] = "running"
    op_row["updated_at"] = _now()
    _save("operation_logs.json", ops)

    # Validate
    if not isinstance(domain, str) or not domain.strip():
        op_row["status"] = "failed"
        op_row["error_message"] = "domain is required and must be a non-empty string."
        op_row["updated_at"] = _now()
        op_row["duration_ms"] = int((time.time() - start) * 1000)
        _save("operation_logs.json", ops)
        return _err("VALIDATION_ERROR", op_row["error_message"])
    if not isinstance(service, str) or not service.strip():
        op_row["status"] = "failed"
        op_row["error_message"] = "service is required and must be a non-empty string."
        op_row["updated_at"] = _now()
        op_row["duration_ms"] = int((time.time() - start) * 1000)
        _save("operation_logs.json", ops)
        return _err("VALIDATION_ERROR", op_row["error_message"])
    domain = domain.strip()
    service = service.strip()

    # Basic HA-ish identifier validation: lowercase letters, digits, underscore
    pat = re.compile(r"^[a-z0-9_]+$")
    if not pat.match(domain) or not pat.match(service):
        op_row["status"] = "failed"
        op_row["error_message"] = "domain/service must match ^[a-z0-9_]+$."
        op_row["updated_at"] = _now()
        op_row["duration_ms"] = int((time.time() - start) * 1000)
        _save("operation_logs.json", ops)
        return _err("VALIDATION_ERROR", op_row["error_message"])

    if data is not None and not isinstance(data, dict):
        op_row["status"] = "failed"
        op_row["error_message"] = "data must be an object or null."
        op_row["updated_at"] = _now()
        op_row["duration_ms"] = int((time.time() - start) * 1000)
        _save("operation_logs.json", ops)
        return _err("VALIDATION_ERROR", op_row["error_message"])

    # In offline datastore mode, we cannot verify service existence in HA; return a deterministic acknowledgement
    # while persisting the audit trail.
    instances_by_id = {r.get("id"): r for r in instances if r.get("id")}
    inst = instances_by_id.get(instance_id)
    if not inst:
        op_row["status"] = "failed"
        op_row["error_message"] = "Instance not found."
        op_row["updated_at"] = _now()
        op_row["duration_ms"] = int((time.time() - start) * 1000)
        _save("operation_logs.json", ops)
        return _err("NOT_FOUND", op_row["error_message"])

    # Update last_seen_at even though call isn't truly executed (mirrors "attempted interaction")
    inst["last_seen_at"] = _now()
    inst["updated_at"] = _now()
    _save("ha_instances.json", instances)

    op_row["status"] = "succeeded"
    op_row["response_summary"] = {
        "called": True,
        "domain": domain,
        "service": service,
        "data_keys": sorted(list((data or {}).keys())),
        "note": "Service call recorded; actual HA service execution is not performed in offline datastore mode.",
    }
    op_row["updated_at"] = _now()
    op_row["duration_ms"] = int((time.time() - start) * 1000)
    _save("operation_logs.json", ops)

    return {
        "instance_id": instance_id,
        "domain": domain,
        "service": service,
        "data": data,
        "result": {"called": True},
        "operation_id": op_id,
    }

def get_history(entity_id, hours=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, request_obj, entity_id_for_log=None, error_message=None, response_summary=None, duration_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "get_history",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": entity_id_for_log,
            "service_domain": None,
            "service_name": None,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    # Validate
    if not isinstance(entity_id, str) or not entity_id.strip() or "." not in entity_id:
        return _err("VALIDATION_ERROR", "entity_id must be a non-empty string like 'domain.object_id'")
    if hours is None:
        hours = 24
    if not isinstance(hours, int) or not (1 <= hours <= 168):
        return _err("VALIDATION_ERROR", "hours must be between 1 and 168")

    instances = _load("ha_instances.json")
    entities = _load("entities.json")
    hist = _load("entity_state_history.json")
    logs = _load("operation_logs.json")

    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")
    instance_id = inst.get("id")

    op_row = _append_op(logs, instance_id, "queued", {"entity_id": entity_id, "hours": hours}, entity_id_for_log=entity_id)
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    # If entity isn't found in default instance, do not fail immediately: history may exist, or entity may belong to another instance.
    ent = None
    for r in entities:
        if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("entity_id") == entity_id:
            ent = r
            break

    # Determine which instance to query history from: prefer the entity's instance; else any eligible instance that has history for that entity_id.
    target_instance_id = instance_id
    if ent and ent.get("status") != "removed":
        target_instance_id = instance_id
    else:
        # search history across eligible instances
        eligible_instances = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible_instances.sort(key=key)
        found_inst = None
        for inst2 in eligible_instances:
            iid = inst2.get("id")
            for h in hist:
                if isinstance(h, dict) and h.get("instance_id") == iid and h.get("entity_id") == entity_id:
                    found_inst = iid
                    break
            if found_inst:
                break
        if found_inst:
            target_instance_id = found_inst

    cutoff = _now_dt() - datetime.timedelta(hours=hours)

    rows = []
    for h in hist:
        if not isinstance(h, dict):
            continue
        if h.get("instance_id") != target_instance_id:
            continue
        if h.get("entity_id") != entity_id:
            continue
        dt = _parse_dt(h.get("changed_at"))
        if not dt:
            continue
        if dt >= cutoff:
            rows.append((dt, h))

    rows.sort(key=lambda x: x[0])
    states = []
    for dt, h in rows:
        states.append({
            "changed_at": h.get("changed_at"),
            "state": h.get("state"),
            "attributes": h.get("attributes") if isinstance(h.get("attributes"), dict) else h.get("attributes"),
            "source": h.get("source"),
        })

    # If we have no history and entity doesn't exist anywhere in mirror, return NOT_FOUND (business rule).
    if not states:
        entity_exists_anywhere = False
        for r in entities:
            if isinstance(r, dict) and r.get("entity_id") == entity_id and r.get("status") != "removed":
                entity_exists_anywhere = True
                break
        if not entity_exists_anywhere:
            dur = int((time.time() - t0) * 1000)
            op_row["status"] = "failed"
            op_row["duration_ms"] = dur
            op_row["error_message"] = f"Entity not found: {entity_id}"
            op_row["response_summary"] = {"count": 0}
            op_row["updated_at"] = _now_iso()
            _save("operation_logs.json", logs)
            return _err("NOT_FOUND", "Entity not found in mirror.", entity_id=entity_id)

    first_changed = states[0]["changed_at"] if states else None
    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = {"count": len(states), "first_changed": first_changed}
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    # touch instance last_seen_at
    now_iso = _now_iso()
    for r in instances:
        if isinstance(r, dict) and r.get("id") == target_instance_id:
            r["last_seen_at"] = now_iso
            r["updated_at"] = now_iso
            break
    _save("ha_instances.json", instances)

    return {
        "instance_id": target_instance_id,
        "entity_id": entity_id,
        "hours": hours,
        "count": len(states),
        "first_changed": first_changed,
        "states": states,
    }

def get_error_log(max_lines=None, since=None, include_text=None, **_extra):
    import json, os, datetime, time, uuid, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, request_obj, error_message=None, response_summary=None, duration_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "get_error_log",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": None,
            "service_domain": None,
            "service_name": None,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    # Validate inputs
    if max_lines is None:
        max_lines = 200
    if not isinstance(max_lines, int) or max_lines <= 0 or max_lines > 5000:
        return _err("VALIDATION_ERROR", "max_lines must be a positive integer <= 5000")
    if include_text is None:
        include_text = False
    if not isinstance(include_text, bool):
        return _err("VALIDATION_ERROR", "include_text must be a boolean when provided")
    since_dt = None
    if since is not None:
        if not isinstance(since, str) or not since.strip():
            return _err("VALIDATION_ERROR", "since must be an ISO 8601 date-time string when provided")
        since_dt = _parse_dt(since)
        if since_dt is None:
            return _err("VALIDATION_ERROR", "since must be a valid ISO 8601 date-time string")

    instances = _load("ha_instances.json")
    logs = _load("operation_logs.json")
    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")
    instance_id = inst.get("id")

    op_row = _append_op(logs, instance_id, "queued", {"max_lines": max_lines, "since": since, "include_text": include_text})
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    # Offline environment: no HA log to fetch. Provide useful summary from operation_logs failures.
    # Only persist response_summary (business rule).
    err_recs = []
    for r in logs:
        if not isinstance(r, dict):
            continue
        if r.get("instance_id") != instance_id:
            continue
        if r.get("status") != "failed":
            continue
        ts = _parse_dt(r.get("created_at"))
        if since_dt and ts and ts < since_dt:
            continue
        msg = r.get("error_message")
        if isinstance(msg, str) and msg.strip():
            err_recs.append((ts or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), msg.strip()))
    err_recs.sort(key=lambda x: x[0])
    err_recs = err_recs[-max_lines:]

    error_count = 0
    warning_count = 0
    integration_mentions = {}
    lines = []
    for ts, msg in err_recs:
        # treat failed ops as ERROR
        error_count += 1
        line = f"{(ts.isoformat() if isinstance(ts, datetime.datetime) else '')} ERROR {msg}".strip()
        lines.append(line)
        # naive integration extraction: words like domain.something or integration name in message
        for m in re.findall(r"\b([a-z_]+)\.", msg):
            integration_mentions[m] = integration_mentions.get(m, 0) + 1

    response_summary = {
        "source": "operation_logs",
        "window": {"since": since, "max_lines": max_lines},
        "error_count": error_count,
        "warning_count": warning_count,
        "integration_mentions": integration_mentions,
        "returned_lines": len(lines),
        "includes_text": bool(include_text),
    }

    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = response_summary
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    # Update instance last_seen_at
    now_iso = _now_iso()
    inst["last_seen_at"] = now_iso
    inst["updated_at"] = now_iso
    _save("ha_instances.json", instances)

    out = {
        "instance_id": instance_id,
        "error_count": error_count,
        "warning_count": warning_count,
        "integration_mentions": integration_mentions,
    }
    if include_text:
        # do NOT persist full text; just return it
        out["log_text"] = "\n".join(lines)
    else:
        out["log_text"] = None
    return out

def sync_instance(include_entities=None, include_automations=None, history_hours=None, source=None, full_refresh=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_dt():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now_dt().isoformat()

    def _parse_dt(x):
        if not x:
            return None
        if isinstance(x, datetime.datetime):
            return x if x.tzinfo else x.replace(tzinfo=datetime.timezone.utc)
        if isinstance(x, str):
            s = x.strip()
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            try:
                dt = datetime.datetime.fromisoformat(s)
                return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                return None
        return None

    def _new_id(prefix):
        return f"hass_{prefix}_{uuid.uuid4().hex[:26]}".replace("__", "_")

    def _choose_instance(instances):
        eligible = [r for r in instances if isinstance(r, dict) and r.get("status") in ("active", "degraded", "offline")]
        if not eligible:
            return None
        def key(r):
            dt = _parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
            return (dt, r.get("id") or "")
        eligible.sort(key=key)
        return eligible[0]

    def _append_op(logs, instance_id, status, request_obj, error_message=None, response_summary=None, duration_ms=None):
        now = _now_iso()
        row = {
            "id": _new_id("op"),
            "instance_id": instance_id,
            "tool_name": "sync_instance",
            "request": request_obj if isinstance(request_obj, dict) else {},
            "entity_id": None,
            "service_domain": None,
            "service_name": None,
            "response_summary": response_summary,
            "error_message": error_message,
            "duration_ms": duration_ms,
            "status": status,
            "created_at": now,
            "updated_at": now,
        }
        logs.append(row)
        return row

    # Defaults
    if include_entities is None: include_entities = True
    if include_automations is None: include_automations = True
    if source is None: source = "ha_history_api"
    if full_refresh is None: full_refresh = False

    # Validate inputs
    if not isinstance(include_entities, bool):
        return _err("VALIDATION_ERROR", "include_entities must be a boolean")
    if not isinstance(include_automations, bool):
        return _err("VALIDATION_ERROR", "include_automations must be a boolean")
    if not (history_hours is None or isinstance(history_hours, int)):
        return _err("VALIDATION_ERROR", "history_hours must be an integer or null")
    if isinstance(history_hours, int) and not (1 <= history_hours <= 168):
        return _err("VALIDATION_ERROR", "history_hours must be between 1 and 168")
    if source not in ("ha_history_api", "state_stream", "manual_import"):
        return _err("VALIDATION_ERROR", "source must be one of: ha_history_api, state_stream, manual_import")
    if not isinstance(full_refresh, bool):
        return _err("VALIDATION_ERROR", "full_refresh must be a boolean")

    instances = _load("ha_instances.json")
    ents = _load("entities.json")
    autos = _load("automations.json")
    hist = _load("entity_state_history.json")
    logs = _load("operation_logs.json")

    inst = _choose_instance(instances)
    if not inst:
        return _err("UNAUTHORIZED", "No enabled Home Assistant instance is available.")
    instance_id = inst.get("id")

    # Audit row queued->running
    op_row = _append_op(
        logs,
        instance_id,
        "queued",
        {
            "include_entities": include_entities,
            "include_automations": include_automations,
            "history_hours": history_hours,
            "source": source,
            "full_refresh": full_refresh,
        },
    )
    op_row["status"] = "running"
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    # Offline: "sync" means mark last_sync_at and per-row last_synced_at as refreshed without fabricating new HA data.
    now_iso = _now_iso()
    updated_entities = 0
    updated_automations = 0
    ingested_history = 0

    if include_entities:
        for r in ents:
            if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("status") != "removed":
                if full_refresh or not r.get("last_synced_at"):
                    r["last_synced_at"] = now_iso
                    r["updated_at"] = now_iso
                    updated_entities += 1

    if include_automations:
        for r in autos:
            if isinstance(r, dict) and r.get("instance_id") == instance_id and r.get("status") == "active":
                if full_refresh or not r.get("last_synced_at"):
                    r["last_synced_at"] = now_iso
                    r["updated_at"] = now_iso
                    updated_automations += 1

    if history_hours is not None:
        # Do not invent history; just ensure uniqueness and optionally "touch" recent rows as seen by this sync source.
        cutoff = _now_dt() - datetime.timedelta(hours=history_hours)
        for r in hist:
            if not isinstance(r, dict):
                continue
            if r.get("instance_id") != instance_id:
                continue
            dt = _parse_dt(r.get("changed_at"))
            if not dt or dt < cutoff:
                continue
            # lifecycle rule: source is immutable; do not change it, but we can mark updated_at as re-indexed if more complete isn't known.
            if full_refresh:
                r["updated_at"] = now_iso
                ingested_history += 1

    # Persist changes (real effect)
    if include_entities:
        _save("entities.json", ents)
    if include_automations:
        _save("automations.json", autos)
    if history_hours is not None and full_refresh:
        _save("entity_state_history.json", hist)

    # Update instance sync markers
    inst["last_seen_at"] = now_iso
    inst["last_sync_at"] = now_iso
    inst["updated_at"] = now_iso
    _save("ha_instances.json", instances)

    dur = int((time.time() - t0) * 1000)
    op_row["status"] = "succeeded"
    op_row["duration_ms"] = dur
    op_row["response_summary"] = {
        "updated_entities": updated_entities,
        "updated_automations": updated_automations,
        "touched_history_rows": ingested_history,
        "history_hours": history_hours,
        "source": source,
        "full_refresh": full_refresh,
    }
    op_row["updated_at"] = _now_iso()
    _save("operation_logs.json", logs)

    return {
        "instance_id": instance_id,
        "synced": True,
        "updated_entities": updated_entities,
        "updated_automations": updated_automations,
        "touched_history_rows": ingested_history,
        "last_sync_at": inst.get("last_sync_at"),
        "operation_id": op_row.get("id"),
    }

def update_instance(name=None, base_url=None, token_ref=None, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Validate
    if not (name is None or isinstance(name, str)):
        return _err("VALIDATION_ERROR", "name must be a string or null")
    if not (base_url is None or isinstance(base_url, str)):
        return _err("VALIDATION_ERROR", "base_url must be a string or null")
    if not (token_ref is None or isinstance(token_ref, str)):
        return _err("VALIDATION_ERROR", "token_ref must be a string or null")
    if not (status is None or isinstance(status, str)):
        return _err("VALIDATION_ERROR", "status must be a string or null")
    if status is not None and status not in ("active", "degraded", "offline", "disabled"):
        return _err("VALIDATION_ERROR", "status must be one of: active, degraded, offline, disabled, null")

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return None

    ha_instances = _load("ha_instances.json")
    op_logs = _load("operation_logs.json")

    eligible = [r for r in ha_instances if isinstance(r, dict)]
    if not eligible:
        return _err("NOT_FOUND", "No Home Assistant instance exists")

    eligible.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), str(r.get("id") or "")))
    instance = eligible[0]

    # Validate uniqueness(base_url)
    if base_url is not None:
        if base_url.strip() == "":
            return _err("VALIDATION_ERROR", "base_url must be non-empty")
        for r in ha_instances:
            if r is instance:
                continue
            if isinstance(r, dict) and r.get("base_url") == base_url:
                return _err("CONFLICT", "base_url must be unique")

    if name is not None and name.strip() == "":
        return _err("VALIDATION_ERROR", "name must be non-empty")
    if token_ref is not None and token_ref.strip() == "":
        return _err("VALIDATION_ERROR", "token_ref must be non-empty")

    # Status transitions
    transitions = {
        "active": {"degraded", "offline", "disabled"},
        "degraded": {"active", "offline", "disabled"},
        "offline": {"active", "degraded", "disabled"},
        "disabled": {"active"},
    }
    cur_status = instance.get("status")
    if cur_status not in transitions:
        return _err("VALIDATION_ERROR", "Instance has invalid current status")
    if status is not None:
        if status == cur_status:
            pass
        elif status not in transitions[cur_status]:
            return _err("INVALID_TRANSITION", f"Illegal status transition: {cur_status} -> {status}")

    # Apply mutations; ensure at least one change
    changed = False
    if name is not None and name != instance.get("name"):
        instance["name"] = name
        changed = True
    if base_url is not None and base_url != instance.get("base_url"):
        instance["base_url"] = base_url
        changed = True
    if token_ref is not None and token_ref != instance.get("token_ref"):
        instance["token_ref"] = token_ref
        changed = True
    if status is not None and status != instance.get("status"):
        instance["status"] = status
        changed = True

    if not changed:
        return _err("NOT_FOUND", "No changes applied (fields identical or no fields provided)")

    instance["updated_at"] = now
    _save("ha_instances.json", ha_instances)

    # Audit row: use closest tool enum "system_overview" as above
    op_id = f"op_{__import__('uuid').uuid4().hex}"
    op_logs.append({
        "id": op_id,
        "instance_id": instance["id"],
        "tool_name": "system_overview",
        "request": {"name": name, "base_url": base_url, "token_ref": token_ref, "status": status},
        "entity_id": None,
        "service_domain": None,
        "service_name": None,
        "response_summary": {"updated_fields": [k for k, v in (("name", name), ("base_url", base_url), ("token_ref", token_ref), ("status", status)) if v is not None]},
        "error_message": None,
        "duration_ms": int((time.time() - t0) * 1000),
        "status": "succeeded",
        "created_at": now,
        "updated_at": now,
    })
    _save("operation_logs.json", op_logs)

    return {"data": {"instance": instance}}

def list_operation_logs(status=None, tool_name=None, entity_id=None, since=None, until=None, limit=None, offset=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0178000" if __import__("os").path.isdir("./environment_mix/0178000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if limit is None: limit = 100
    if offset is None: offset = 0

    # Validate
    if not (status is None or (isinstance(status, str) and status in ("queued", "running", "succeeded", "failed", "cancelled"))):
        return _err("VALIDATION_ERROR", "status filter is invalid")
    if not (tool_name is None or isinstance(tool_name, str)):
        return _err("VALIDATION_ERROR", "tool_name must be a string or null")
    if not (entity_id is None or isinstance(entity_id, str)):
        return _err("VALIDATION_ERROR", "entity_id must be a string or null")
    if not isinstance(limit, int) or not (1 <= limit <= 500):
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 500")
    if not isinstance(offset, int) or offset < 0:
        return _err("VALIDATION_ERROR", "offset must be an integer >= 0")

    def _parse_dt_filter(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str):
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an ISO date-time string or null")
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc), None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a valid ISO date-time string")
    since_dt, e1 = _parse_dt_filter(since, "since")
    if e1: return e1
    until_dt, e2 = _parse_dt_filter(until, "until")
    if e2: return e2
    if since_dt and until_dt and since_dt > until_dt:
        return _err("VALIDATION_ERROR", "since must be <= until")

    ha_instances = _load("ha_instances.json")
    op_logs = _load("operation_logs.json")

    # Authorization: no auth model exists; deny only if no instance exists to bind audit read.
    if not ha_instances:
        return _err("UNAUTHORIZED", "Not authorized to view audit logs")

    def _parse_created(r):
        s = r.get("created_at")
        if not isinstance(s, str):
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        try:
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
        except Exception:
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)

    # Filter
    rows = []
    for r in op_logs:
        if not isinstance(r, dict):
            continue
        if status is not None and r.get("status") != status:
            continue
        if tool_name is not None and r.get("tool_name") != tool_name:
            continue
        if entity_id is not None and r.get("entity_id") != entity_id:
            continue
        cd = _parse_created(r)
        if since_dt is not None and cd < since_dt:
            continue
        if until_dt is not None and cd > until_dt:
            continue
        rows.append(r)

    # Sort newest-first
    rows.sort(key=lambda r: (_parse_created(r), str(r.get("id") or "")), reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    has_more = offset + limit < total

    # Record this read in operation_logs with queued->running->succeeded (audit requirement)
    # Bind to deterministic instance
    def _select_instance_id():
        def _parse_dt(s):
            if s is None or not isinstance(s, str): return None
            try:
                if s.endswith("Z"): s2 = s[:-1] + "+00:00"
                else: s2 = s
                return datetime.datetime.fromisoformat(s2).astimezone(datetime.timezone.utc)
            except Exception:
                return None
        eligible = [r for r in ha_instances if isinstance(r, dict)]
        eligible.sort(key=lambda r: (_parse_dt(r.get("created_at")) or datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), str(r.get("id") or "")))
        return eligible[0].get("id") if eligible else None

    inst_id = _select_instance_id()
    if inst_id:
        import uuid
        op_id = f"op_{uuid.uuid4().hex}"
        audit = {
            "id": op_id,
            "instance_id": inst_id,
            "tool_name": "system_overview",
            "request": {"status": status, "tool_name": tool_name, "entity_id": entity_id, "since": since, "until": until, "limit": limit, "offset": offset},
            "entity_id": None,
            "service_domain": None,
            "service_name": None,
            "response_summary": {"returned": len(page), "total": total, "has_more": has_more},
            "error_message": None,
            "duration_ms": int((time.time() - t0) * 1000),
            "status": "succeeded",
            "created_at": now,
            "updated_at": now,
        }
        op_logs.append(audit)
        _save("operation_logs.json", op_logs)

    return {"data": {"rows": page, "total": total, "limit": limit, "offset": offset, "has_more": has_more}}
